"""Propose Winner: record what became of each new model, and leave a winner for a human.

A new model wins when, on some target, the winner holds its quality and one
of its steps runs on that model. Each target with such a winner becomes a
proposal: its experiment and the `azathoth workflow promote` command that
promotes it. The step never promotes; a person does, when they choose.

Every new model is then recorded in the ledger: `proposed`, with the
workflows it won, or `rejected`. A rejected model the watch added tonight is
deauthorized again, so this machine's portfolio holds only what someone
chose; one authorized before tonight is left as it was. When a target could
not be tried, the models that won nothing are deauthorized but not recorded,
so the next run tries them again.
"""

import json
import os
import sys
from datetime import UTC, datetime
from pathlib import Path

from azathoth import api

LEDGER_VERSION = 1


class WatchError(Exception):
    """The watch cannot go on; the message says why."""


def read_ledger(path):
    try:
        ledger = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, ValueError):
        raise WatchError(f"The ledger at {path} could not be read as JSON.") from None

    if (
        not isinstance(ledger, dict)
        or ledger.get("version") != LEDGER_VERSION
        or not isinstance(ledger.get("models"), dict)
    ):
        raise WatchError(f"The ledger at {path} is not a model-watch ledger.")

    return ledger


def write_ledger(path, ledger):
    path.parent.mkdir(parents=True, exist_ok=True)
    written = path.with_name(f"{path.name}.tmp")
    written.write_text(f"{json.dumps(ledger, indent=2, sort_keys=True)}\n", encoding="utf-8")
    os.replace(written, path)


def plural(count, one, many):
    return f"{count} {one if count == 1 else many}"


def propose(ledger, compared, new_models, added, portfolio, *, now, missing, refused):
    """Return what the step says, and the ledger after it, deauthorizing the losers it added.

    `missing` is the error deauthorizing a model no longer authorized fails
    with, which leaves nothing to take back. `refused` are the others it may
    fail with; such a model is named, and left authorized.
    """

    stamp = now.astimezone(UTC).isoformat(timespec="seconds")
    won = {}
    proposals = []

    for target in compared:
        if target.get("problem") is None and target["holds_quality"] and target["new_models_used"]:
            proposals.append(
                {
                    "workflow": target["workflow"],
                    "experiment": target["experiment"],
                    "new_models_used": target["new_models_used"],
                    "cost_percent": target["cost_percent"],
                    "command": target["command"],
                }
            )

            for identifier in target["new_models_used"]:
                won.setdefault(identifier, []).append(target["workflow"])

    complete = all(target.get("problem") is None for target in compared)
    models = dict(ledger["models"])
    kept_authorized = []

    for model in new_models:
        identifier = model["identifier"]

        if identifier in won:
            models[identifier] = {"seen": stamp, "status": "proposed", "won": won[identifier]}
            continue

        if identifier in added:
            try:
                portfolio.remove(identifier)
            except missing:
                pass
            except refused:
                kept_authorized.append(identifier)

        if complete:
            models[identifier] = {"seen": stamp, "status": "rejected"}

    rejected = [model["identifier"] for model in new_models if model["identifier"] not in won]

    if proposals:
        message = f"Waiting for a human: {plural(len(proposals), 'proposal', 'proposals')}."
    else:
        message = "Nothing to propose tonight."

    if rejected:
        message = f"{message} {plural(len(rejected), 'new model', 'new models')} rejected."

    if not complete:
        message = f"{message} Not every target was tried, so the rejected are tried again."

    said = {
        "proposals": proposals,
        "rejected": rejected,
        "kept_authorized": kept_authorized,
        "message": message,
    }

    return said, {**ledger, "models": models}


def main():
    inputs = json.load(sys.stdin)
    database = os.environ.get("AZATHOTH_DATABASE", "azathoth.db")

    try:
        path = Path(os.path.expanduser(inputs["ledger"]))
        ledger = read_ledger(path)

        with api.open(database) as instance:
            said, updated = propose(
                ledger,
                inputs["compared"],
                inputs.get("new_models", []),
                set(inputs.get("added", [])),
                instance.portfolio,
                now=datetime.now(UTC),
                missing=api.NotFoundError,
                refused=api.ApiError,
            )
    except (WatchError, api.ApiError) as exc:
        sys.stderr.buffer.write(str(exc).encode("utf-8"))
        sys.exit(1)

    write_ledger(path, updated)
    json.dump(said, sys.stdout)


if __name__ == "__main__":
    main()
